import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第二卷 回潮 · 第33章 中秋","description":"","frontmatter":{},"headers":[],"relativePath":"第33章_中秋.md","filePath":"第33章_中秋.md"}'),r={name:"第33章_中秋.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第二卷-回潮-·-第33章-中秋" tabindex="-1">第二卷 回潮 · 第33章 中秋 <a class="header-anchor" href="#第二卷-回潮-·-第33章-中秋" aria-label="Permalink to &quot;第二卷 回潮 · 第33章 中秋&quot;">​</a></h1><p>放假前最后一节课后，教室空得很快。</p><p>江苒收包收到一半，抬头看我，没说话。我们冷了两天了，起因是一张纸条。顾远闹着抽走我写了一半的东西，当众念了一句，陈默跟着笑。她当场转过脸，说我什么都藏，连一句当面的话都不肯给。我慢了一拍，没接住。</p><p>她把包带一提，铃铛响了一声。</p><p>“中秋各回各家，你好好过。”</p><p>我说好。她走出门，风把她桌角那颗没折完的纸星星吹到我桌上，淡黄色的，瘪着一角。我把它攥进口袋。</p><p>校门口人很多，林小满拉着何晓去买橘子汽水，秦浩抱着球不撒手，他们还在争月饼的馅。叶老师站在走廊上说假后见。我穿过这片热闹，坐车回了雾河边。</p><p>宋阿婆坐在门口剥枇杷，汁水沾在指尖上，香很淡。她见我耷拉着脸，塞给我一颗海盐糖，咸甜的，说败火。我在她旁边坐下，听剪刀开合的轻响，看筐里的皮一点点堆高，心里那团燥，一点点被晚风吹薄。</p><p>晚上家里蒸米糕，芝麻花生馅，粘牙。爸翻出一张老唱片放上，沙沙的底噪里，有人慢悠悠唱潮水。妈问学校好不好，我说好。嘴上说好，心里全是江苒转过去的侧脸。</p><p>月亮上来后，我走到院子里，给她打电话。</p><p>响了很久，那边才接。</p><p>“喂。”她声音轻轻的。</p><p>“是我。”我说。</p><p>“知道。”她顿了顿，“你那边，有河水声吗。”</p><p>我把手机往堤的方向偏了偏，风里果然有水声，细细的，推着走。</p><p>“听到了吗。”我问。</p><p>“听到了。”她说，“我这边只有切月饼的声音。”</p><p>僵着的那点东西，被水声泡软了些。</p><p>“你没折完的那颗，在我这。”我说，“我捏好了，鼓起来了。加上之前的，正好第七颗。我刚才数了数，一共七颗。”</p><p>她那边静了几秒，有纸摩擦的轻响。</p><p>“沈聿，我没气顾远。”她低声说，“我气你不说。你纸上写那么多，当面倒一个字也没有。”</p><p>我摩挲着那颗星星，尖角硌着指腹。</p><p>“我说话慢，一急就乱。写字快些。”</p><p>“我知道你慢。”她叹气，“我一快，就怕把你丢下。”</p><p>心口像喝了一口薄荷水，又凉又醒。</p><p>“我以后走快点，你走慢点，我们在中间碰头。”我说。</p><p>她笑了，铃铛似的。</p><p>“纸条的事，原谅你了。中秋晚上，不许藏了，要说出来。”</p><p>我抬头看月亮，又圆又亮，像泡在水里。院角有桂花香，混着米糕的甜。</p><p>“江苒，中秋快乐。”我说，“从校门口到河堤，我一路都在想你。”</p><p>那边安静了一会儿，才很小声回：“我也想你，比你多一点。”</p><p>耳朵一下烫起来。我赶紧问她吃了什么馅，她说莲蓉，太甜，灌了两口薄荷水。我说我家粘牙的，她笑我说话要被粘住。</p><p>唱针滑到尽头，沙沙响了一阵就停了，院子静下来，只剩河水声。</p><p>“你去河边吧。”她忽然说，“我去阳台，开着电话，一起看月亮。”</p><p>我披上外套往堤上走。露水洇湿鞋面，草腥混着泥味。站上堤，雾河一下铺开，满河月光碎成小块，又聚拢，像谁撒了一把碎光，又一点点捡回去。潮气贴着小腿往上爬，带着水草的凉。我把外套拉紧些，电话贴着耳朵，她的呼吸混着水声，一下就觉得两岸离得很近。</p><p>“河里有月亮，你呢。”我问。</p><p>“我阳台只能看到小小一块。”她说，“你的大，替我多看一眼。”</p><p>我扔了颗小石子下去，水纹荡开，凉汽扑到脸上。</p><p>“第七颗放哪了。”她问。</p><p>“放心口的口袋。”我说，“回去给你。第八颗一起折。”</p><p>“电话里拉钩不算，回来补上。”</p><p>“好，用星星盖章。”</p><p>她笑了一阵，又轻下去：“沈聿，我阳台上也折了一颗，也是第七颗，我们折重了。”</p><p>我看着河面，心口那颗像热起来。</p><p>“那就两颗第七颗，凑一对。一颗放你那，一颗放我这。”</p><p>风大起来，水声一下一下，很稳。月光落在河面，也落在我手背上。我想，此刻她阳台的栏杆上，应该也落着同一片光。</p><p>谁也不舍得先挂。沉默里，只有呼吸和水声。</p><p>快说晚安时，她忽然压低声音：“沈聿，你听，河水里是不是有铃铛声。”</p><p>我屏住呼吸，朝月光正中看去。水面晃着一小片亮，像什么东西顺着潮，正朝我漂过来。</p>',49)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
